from .devices.keysight_n9935a import KeysightN9935A
from .devices.keysight_n9020a import KeysightN9020A
from .devices.keysight_n9040b import KeysightN9040B


class SupportedSignalAnalyzers(object):
    """ Model names of supported signal analyzers and their appropriate handlers (dedicated Python classes) """

    _keysight_n9935a = KeysightN9935A
    _keysight_n9020a = KeysightN9020A
    _keysight_n9040b = KeysightN9040B

    models = (_keysight_n9935a.__name__.lower(),
              _keysight_n9020a.__name__.lower(),
              _keysight_n9040b.__name__.lower())

    handlers = {_keysight_n9935a.__name__.lower(): _keysight_n9935a,
                _keysight_n9020a.__name__.lower(): _keysight_n9020a,
                _keysight_n9040b.__name__.lower(): _keysight_n9040b}
